import{_ as o,c as a,o as t,a3 as r}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Guía de Uso - Reporte RemitoVSCompras","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/RemitosVsCompras.md","filePath":"reportes/RemitosVsCompras.md","lastUpdated":1759238350000}'),i={name:"reportes/RemitosVsCompras.md"};function s(l,e,d,n,c,p){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="guia-de-uso-reporte-remitovscompras" tabindex="-1">Guía de Uso - Reporte RemitoVSCompras <a class="header-anchor" href="#guia-de-uso-reporte-remitovscompras" aria-label="Permalink to &quot;Guía de Uso - Reporte RemitoVSCompras&quot;">​</a></h1><p>El reporte <strong>RemitoVSCompras</strong> es una herramienta analítica que permite:</p><ul><li><strong>Comparar</strong> órdenes de compra con remitos de entrega</li><li><strong>Identificar discrepancias</strong> entre lo comprado y lo recibido</li><li><strong>Analizar</strong> precios, cantidades y tiempos de entrega</li></ul><h2 id="tabla-de-contenidos" tabindex="-1"><strong>Tabla de Contenidos</strong> <a class="header-anchor" href="#tabla-de-contenidos" aria-label="Permalink to &quot;**Tabla de Contenidos**&quot;">​</a></h2><ol><li><a href="#descripcion-general">Descripción General</a></li><li><a href="#parametros-del-reporte">Parámetros del Reporte</a></li><li><a href="#-comportamiento-de-fechas">Comportamiento de Fechas</a></li><li><a href="#columnas-del-reporte">Columnas del Reporte</a></li><li><a href="#estilo-visual">Estilo Visual</a></li><li><a href="#notas-adicionales">Notas Adicionales</a></li><li><a href="#ejemplos-de-uso">Ejemplos de Uso</a></li><li><a href="#preguntas-frecuentes-faq">Preguntas Frecuentes (FAQ)</a></li></ol><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>El reporte <strong>RemitoVSCompras</strong> es una herramienta clave para el análisis comparativo entre órdenes de compra y remitos de entrega. Permite:</p><ul><li>🔍 <strong>Rastrear</strong> el flujo completo de compras</li><li>⚖️ <strong>Comparar</strong> cantidades compradas vs. entregadas</li><li>📊 <strong>Identificar</strong> discrepancias en precios y cantidades</li><li>📅 <strong>Analizar</strong> tendencias por períodos específicos</li></ul><h3 id="parametros-del-reporte" tabindex="-1"><strong>Parámetros del Reporte</strong> <a class="header-anchor" href="#parametros-del-reporte" aria-label="Permalink to &quot;**Parámetros del Reporte**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Tipo</strong></td><td>Selecciona el enfoque del reporte:<br>- <code>compras</code>: Solo compras<br>- <code>remitos</code>: Solo remitos<br>- <code>todo</code>: Comparativo completo</td><td><code>todo</code></td></tr><tr><td><strong>Fecha Desde/Hasta</strong></td><td>Rango de fechas a analizar. <a href="#comportamiento-de-fechas"><strong>(Ver Comportamiento de Fechas)</strong></a></td><td><code>01/01/2023</code> a <code>31/12/2023</code></td></tr><tr><td><strong>Código Interno</strong></td><td>Filtra por código de artículo <a href="./BusquedaParcial.html"><strong>(búsqueda parcial)</strong></a></td><td><code>INS-2023</code></td></tr><tr><td><strong>Descripcion</strong></td><td>Filtra por descripción/patente/Factura</td><td><code>CAM-001</code></td></tr><tr><td><strong>Proveedor</strong></td><td>Filtra por nombre de proveedor</td><td><code>LOGISTICA S.A.</code></td></tr></tbody></table><h2 id="📅-comportamiento-de-fechas" tabindex="-1">📅 Comportamiento de Fechas <a class="header-anchor" href="#📅-comportamiento-de-fechas" aria-label="Permalink to &quot;📅 Comportamiento de Fechas&quot;">​</a></h2><p>El reporte aplica inteligentemente los rangos de fecha según lo especificado:</p><blockquote><p><a href="./ComportamientoFiltroFechas.html#4-diagrama-de-funcionamiento"><strong>(Ver diagrama)</strong></a></p></blockquote><h3 id="_1-filtrado-por-dia-especifico" tabindex="-1">1. Filtrado por Día Específico <a class="header-anchor" href="#_1-filtrado-por-dia-especifico" aria-label="Permalink to &quot;1. Filtrado por Día Específico&quot;">​</a></h3><p>🔹 <strong>Cuando se ingresa solo una fecha</strong> (inicio o fin)<br> → Muestra exclusivamente registros del <strong>día seleccionado</strong><br><em>Ejemplo útil para:</em></p><ul><li>Verificar todas las transacciones de un día particular</li><li>Auditorías diarias rápidas</li></ul><h3 id="_2-filtrado-por-rango-completo" tabindex="-1">2. Filtrado por Rango Completo <a class="header-anchor" href="#_2-filtrado-por-rango-completo" aria-label="Permalink to &quot;2. Filtrado por Rango Completo&quot;">​</a></h3><p>🔹 <strong>Cuando se especifican ambas fechas</strong><br> → Filtra todos los registros <strong>entre esas fechas inclusive</strong><br> 📌 <em>Recomendado para:</em></p><ul><li>Reportes mensuales/trimestrales</li><li>Análisis de períodos específicos</li></ul><h3 id="_3-comportamiento-por-defecto" tabindex="-1">3. Comportamiento por Defecto <a class="header-anchor" href="#_3-comportamiento-por-defecto" aria-label="Permalink to &quot;3. Comportamiento por Defecto&quot;">​</a></h3><p>🔹 <strong>Sin fechas ingresadas</strong>:</p><table tabindex="0"><thead><tr><th>Tipo Reporte</th><th>Período Mostrado</th><th>Caso de Uso Típico</th></tr></thead><tbody><tr><td><code>&quot;compras&quot;</code></td><td><strong>Últimos 30 días</strong></td><td>Control mensual</td></tr><tr><td><code>&quot;remitos&quot;</code></td><td><strong>Últimos 30 días</strong></td><td>Control de entregas</td></tr><tr><td><code>&quot;todo&quot;</code></td><td><strong>Últimos 30 días</strong></td><td>Análisis operativo</td></tr></tbody></table><blockquote><h4 id="💡-mejores-practicas" tabindex="-1">💡 Mejores Prácticas <a class="header-anchor" href="#💡-mejores-practicas" aria-label="Permalink to &quot;💡 Mejores Prácticas&quot;">​</a></h4><ul><li><p>Para <strong>análisis puntual</strong>: Usar filtro de día único</p></li><li><p>Para <strong>tendencias</strong>: Siempre definir rango completo</p></li><li><p>Para <strong>reportes recurrentes</strong>:</p><p><code>Fecha Desde:</code> Primer día del mes <br> &gt; <code>Fecha Hasta:</code> Último día del mes</p></li></ul></blockquote><h2 id="columnas-del-reporte" tabindex="-1">Columnas del Reporte <a class="header-anchor" href="#columnas-del-reporte" aria-label="Permalink to &quot;Columnas del Reporte&quot;">​</a></h2><h3 id="columnas-comunes" tabindex="-1">Columnas Comunes <a class="header-anchor" href="#columnas-comunes" aria-label="Permalink to &quot;Columnas Comunes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Columna</th><th>Descripción</th></tr></thead><tbody><tr><td>Articulo</td><td>Nombre del artículo</td></tr><tr><td>Descripcion</td><td>Patente/descripción asociada</td></tr><tr><td>Proveedor</td><td>Nombre del proveedor</td></tr><tr><td>Notas</td><td>Observaciones adicionales (muestra &quot;-&quot; si está vacío)</td></tr><tr><td>Precio unitario</td><td>Precio por unidad (formato monetario)</td></tr><tr><td>Precio Total</td><td>Precio total (cantidad × precio unitario, formato monetario)</td></tr></tbody></table><h3 id="columnas-segun-tipo-de-reporte" tabindex="-1">Columnas según Tipo de Reporte <a class="header-anchor" href="#columnas-segun-tipo-de-reporte" aria-label="Permalink to &quot;Columnas según Tipo de Reporte&quot;">​</a></h3><h4 id="para-compras-o-todo" tabindex="-1">Para &quot;compras&quot; o &quot;todo&quot;: <a class="header-anchor" href="#para-compras-o-todo" aria-label="Permalink to &quot;Para &quot;compras&quot; o &quot;todo&quot;:&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Columna</th><th>Descripción</th></tr></thead><tbody><tr><td>Fecha de Compra</td><td>Última fecha de compra del artículo</td></tr><tr><td>Cantidad Compra</td><td>Cantidad total comprada</td></tr></tbody></table><h4 id="para-remitos-o-todo" tabindex="-1">Para &quot;remitos&quot; o &quot;todo&quot;: <a class="header-anchor" href="#para-remitos-o-todo" aria-label="Permalink to &quot;Para &quot;remitos&quot; o &quot;todo&quot;:&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Columna</th><th>Descripción</th></tr></thead><tbody><tr><td>Fecha del Remito</td><td>Última fecha de remito del artículo</td></tr><tr><td>Cantidad Remito</td><td>Cantidad total remitida</td></tr></tbody></table><h4 id="solo-para-todo" tabindex="-1">Solo para &quot;todo&quot;: <a class="header-anchor" href="#solo-para-todo" aria-label="Permalink to &quot;Solo para &quot;todo&quot;:&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Columna</th><th>Descripción</th></tr></thead><tbody><tr><td>Diferencia</td><td>Cantidad comprada - Cantidad remitida (puede ser negativa)</td></tr></tbody></table><h2 id="estilo-visual" tabindex="-1">Estilo Visual <a class="header-anchor" href="#estilo-visual" aria-label="Permalink to &quot;Estilo Visual&quot;">​</a></h2><ul><li>Filas alternadas con fondo gris claro para mejor legibilidad</li><li>Encabezados en color verde oscuro (#486666) con texto blanco</li><li>Formato monetario para precios (ej: $1,234.56)</li><li>Formato de fecha largo (ej: &quot;January 15, 2023&quot;)</li></ul><h2 id="notas-adicionales" tabindex="-1">Notas Adicionales <a class="header-anchor" href="#notas-adicionales" aria-label="Permalink to &quot;Notas Adicionales&quot;">​</a></h2><ol><li>El campo &quot;Notas&quot; muestra información visible al cliente (los campos que comienzan con &quot;Obs&quot; no se muestran)</li><li>Las búsquedas por texto son insensibles a mayúsculas/minúsculas</li><li>Cuando se filtra por &quot;todo&quot;, el reporte muestra las comparaciones lado a lado</li><li>Los valores nulos o vacíos se muestran como &quot;-&quot; para mejor claridad</li></ol><h2 id="ejemplos-de-uso" tabindex="-1">Ejemplos de Uso <a class="header-anchor" href="#ejemplos-de-uso" aria-label="Permalink to &quot;Ejemplos de Uso&quot;">​</a></h2><ol><li><p><strong>Ver todas las compras del último mes</strong>: Dejar todos los parámetros por defecto, establecer <code>tipo</code> = &quot;compras&quot;</p></li><li><p><strong>Comparar compras vs remitos de un artículo específico</strong>: <code>tipo</code> = &quot;todo&quot;, <code>codigoInterno</code> = &quot;ABC123&quot;</p></li><li><p><strong>Ver remitos de un proveedor en un rango de fechas</strong>: <code>tipo</code> = &quot;remitos&quot;, <code>proveedor</code> = &quot;ProveedorX&quot;, <code>fechaDesde</code> = &quot;2023-01-01&quot;, <code>fechaHasta</code> = &quot;2023-01-31&quot;</p></li></ol><h2 id="preguntas-frecuentes-faq" tabindex="-1">Preguntas frecuentes (FAQ) <a class="header-anchor" href="#preguntas-frecuentes-faq" aria-label="Permalink to &quot;Preguntas frecuentes (FAQ)&quot;">​</a></h2><h3 id="🔍-¿por-que-no-veo-datos-en-el-reporte" tabindex="-1">🔍 ¿Por qué no veo datos en el reporte? <a class="header-anchor" href="#🔍-¿por-que-no-veo-datos-en-el-reporte" aria-label="Permalink to &quot;🔍 ¿Por qué no veo datos en el reporte?&quot;">​</a></h3><p>Verifica estos puntos:</p><ol><li><p>🚦 <strong>Parámetros muy restrictivos</strong></p><ul><li>Prueba ampliar los rangos de fecha</li><li>Reduce los filtros de texto</li></ul></li><li><p>📅 <strong>Rango de fechas correcto</strong></p><ul><li>Confirma que las fechas ingresadas contienen registros</li><li>Verifica el formato (DD/MM/AAAA)</li></ul></li><li><p>🗃️ <strong>Existencia de registros</strong></p><ul><li>Consulta con logística si hay datos para esos criterios</li><li>Revisa permisos de visualización</li></ul></li></ol><h2 id="🔎-analisis-de-datos" tabindex="-1">🔎 Análisis de Datos <a class="header-anchor" href="#🔎-analisis-de-datos" aria-label="Permalink to &quot;🔎 Análisis de Datos&quot;">​</a></h2><h3 id="⚖️-¿como-identificar-discrepancias" tabindex="-1">⚖️ ¿Cómo identificar discrepancias? <a class="header-anchor" href="#⚖️-¿como-identificar-discrepancias" aria-label="Permalink to &quot;⚖️ ¿Cómo identificar discrepancias?&quot;">​</a></h3><p>Sigue este flujo:</p><ol><li>Establece <code>Tipo = &quot;todo&quot;</code></li><li>Ordena por columna <strong>&quot;Diferencia&quot;</strong> (click en el encabezado)</li><li>Enfócate en: <ul><li>🔴 Valores <strong>negativos</strong> (prioridad alta)</li><li>🟡 Diferencias <strong>superiores al 10%</strong></li></ul></li><li>Exporta a Excel para cruzar con otros sistemas</li></ol><h2 id="💡-funcionalidades-clave" tabindex="-1">💡 Funcionalidades Clave <a class="header-anchor" href="#💡-funcionalidades-clave" aria-label="Permalink to &quot;💡 Funcionalidades Clave&quot;">​</a></h2><h3 id="🔄-¿que-significa-todo" tabindex="-1">🔄 ¿Qué significa &quot;todo&quot;? <a class="header-anchor" href="#🔄-¿que-significa-todo" aria-label="Permalink to &quot;🔄 ¿Qué significa &quot;todo&quot;?&quot;">​</a></h3><ul><li><p>Muestra <strong>comparación lado a lado</strong>:</p><p><strong>[Compra] vs [Remito] → [Diferencia]</strong></p></li><li><p>Incluye cálculo automático de:</p></li><li><p>Stock pendiente (valores positivos)</p></li><li><p>Sobrereposiciones (valores negativos)</p></li></ul><h2 id="🛠️-uso-avanzado" tabindex="-1">🛠️ Uso Avanzado <a class="header-anchor" href="#🛠️-uso-avanzado" aria-label="Permalink to &quot;🛠️ Uso Avanzado&quot;">​</a></h2><h3 id="✂️-¿como-filtrar-por-multiples-valores" tabindex="-1">✂️ ¿Cómo filtrar por múltiples valores? <a class="header-anchor" href="#✂️-¿como-filtrar-por-multiples-valores" aria-label="Permalink to &quot;✂️ ¿Cómo filtrar por múltiples valores?&quot;">​</a></h3><p>Alternativas disponibles:</p><ol><li><strong>Búsqueda parcial con patrones</strong>:</li></ol><ul><li><code>&quot;MAT-2023%&quot;</code> (códigos que empiecen con...)</li><li><code>&quot;%ENERO%&quot;</code> (contengan el texto)</li></ul><ol start="2"><li><strong>Truco para múltiples proveedores</strong>:</li></ol><p><code>Proveedor:</code>&quot;%CORP% OR %S.A.%&quot;</p><ol start="3"><li>Generar reportes separados y consolidar en Excel</li></ol><h2 id="❓-preguntas-adicionales" tabindex="-1">❓ Preguntas Adicionales <a class="header-anchor" href="#❓-preguntas-adicionales" aria-label="Permalink to &quot;❓ Preguntas Adicionales&quot;">​</a></h2><h3 id="⏱️-¿por-que-tarda-en-generar-el-reporte" tabindex="-1">⏱️ ¿Por qué tarda en generar el reporte? <a class="header-anchor" href="#⏱️-¿por-que-tarda-en-generar-el-reporte" aria-label="Permalink to &quot;⏱️ ¿Por qué tarda en generar el reporte?&quot;">​</a></h3><p><strong>Posibles causas:</strong></p><ul><li>Rango de fechas muy amplio</li><li>Muchos artículos/proveedores seleccionados</li><li>Conexión lenta a la base de datos</li></ul><p>💡 <strong>Solución:</strong><br> Filtrar por períodos mensuales y luego consolidar</p><hr><h3 id="📊-¿como-interpretar-valores-null" tabindex="-1">📊 ¿Cómo interpretar valores NULL? <a class="header-anchor" href="#📊-¿como-interpretar-valores-null" aria-label="Permalink to &quot;📊 ¿Cómo interpretar valores NULL?&quot;">​</a></h3><p><strong>Significados:</strong></p><ul><li><code>Fecha NULL</code>: No existe transacción del tipo opuesto</li><li><code>Diferencia NULL</code>: Falta un lado de la comparación</li><li><code>Precio NULL</code>: Solo aplica a compras</li></ul><hr><h3 id="📲-¿se-puede-usar-en-moviles" tabindex="-1">📲 ¿Se puede usar en móviles? <a class="header-anchor" href="#📲-¿se-puede-usar-en-moviles" aria-label="Permalink to &quot;📲 ¿Se puede usar en móviles?&quot;">​</a></h3><p>✅ Sí, pero con <strong>limitaciones</strong>:</p><ul><li>Mejor experiencia en tablets</li><li>Exportar a PDF para visualización óptima</li><li>Evitar rangos mayores a 3 meses</li></ul><hr><h2 id="🆘-soporte-tecnico" tabindex="-1">🆘 Soporte Técnico <a class="header-anchor" href="#🆘-soporte-tecnico" aria-label="Permalink to &quot;🆘 Soporte Técnico&quot;">​</a></h2><h3 id="tips-utiles-para-pedir-ayuda" tabindex="-1">Tips útiles para pedir ayuda: <a class="header-anchor" href="#tips-utiles-para-pedir-ayuda" aria-label="Permalink to &quot;Tips útiles para pedir ayuda:&quot;">​</a></h3><ul><li>📸 Capturas de pantalla de errores o filtros usados</li><li>📅 Especificar rangos de fecha y tipo de reporte</li><li>📥 Exportar y compartir el Excel si es posible</li></ul><p>📩 <strong>Contacto de soporte</strong>:<br><a href="https://surl.li/kmiuwb" target="_blank" rel="noreferrer"><code>Ingresa al formulario</code></a></p>',76)]))}const h=o(i,[["render",s]]);export{m as __pageData,h as default};
